css:
.panel-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #e0e6f0;
}
.panel-sim-container * {
    box-sizing: border-box;
}
.panel-sim-container .panel-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-left: 4px solid #00bfff;
    padding: 18px 24px;
    margin-bottom: 24px;
    background: linear-gradient(90deg, rgba(0,191,255,0.1), rgba(0,191,255,0) 75%);
    border-radius: 0 8px 8px 0;
    flex-wrap: wrap;
    gap: 16px;
}
.panel-sim-container .panel-sim-header h1 {
    color: #00bfff;
    font-size: 1.4rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0 0 4px 0;
    font-weight: 700;
}
.panel-sim-container .panel-sim-subtitle {
    color: #9ca3af;
    font-size: 0.85rem;
    margin: 0;
    letter-spacing: 0.02em;
}
.panel-sim-container .panel-sim-period-counter {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 999px;
    padding: 8px 18px;
    font-size: 0.78rem;
    color: #9ca3af;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 600;
}
.panel-sim-container .panel-sim-period-counter #currentDay,
.panel-sim-container .panel-sim-period-counter #maxPeriods {
    color: #00ff88;
    font-weight: 700;
    font-size: 1rem;
}

.panel-sim-container .panel-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-top: 3px solid #ff6b35;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.panel-sim-container .panel-sim-briefing h2 {
    color: #ff6b35;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.panel-sim-container .panel-sim-briefing #briefingText {
    color: #c8d1e0;
    font-size: 0.92rem;
    line-height: 1.65;
}
.panel-sim-container .panel-sim-briefing #briefingText p {
    margin: 0 0 10px 0;
}
.panel-sim-container .panel-sim-briefing #briefingText strong {
    color: #00ff88;
    font-weight: 600;
}
.panel-sim-container .panel-sim-briefing #briefingText em {
    color: #9ca3af;
    display: block;
    margin-top: 12px;
    border-top: 1px dashed #1f2d3d;
    padding-top: 10px;
    font-style: italic;
}

.panel-sim-container .panel-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.panel-sim-container .panel-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.panel-sim-container .panel-sim-kpi-card:hover {
    border-color: #2d3f55;
    transform: translateY(-2px);
}
.panel-sim-container .panel-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.panel-sim-container .panel-sim-kpi-label {
    color: #767e8d;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.panel-sim-container .panel-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #00ff88;
    font-variant-numeric: tabular-nums;
    line-height: 1.1;
}

.panel-sim-container .panel-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.panel-sim-container .panel-sim-controls h3 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 18px 0;
    font-weight: 700;
}
.panel-sim-container .panel-sim-control-row {
    display: grid;
    grid-template-columns: 220px 1fr;
    gap: 14px;
    align-items: center;
    margin-bottom: 12px;
}
.panel-sim-container .panel-sim-control-row label {
    color: #9ca3af;
    font-size: 0.78rem;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 600;
}
.panel-sim-container .panel-sim-controls select,
.panel-sim-container .panel-sim-controls input[type="text"],
.panel-sim-container .panel-sim-controls input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    appearance: none;
    -webkit-appearance: none;
    background-image: linear-gradient(45deg, transparent 50%, #00bfff 50%), linear-gradient(135deg, #00bfff 50%, transparent 50%);
    background-position: calc(100% - 18px) 50%, calc(100% - 12px) 50%;
    background-size: 6px 6px, 6px 6px;
    background-repeat: no-repeat;
    padding-right: 32px;
}
.panel-sim-container .panel-sim-controls input[type="text"],
.panel-sim-container .panel-sim-controls input[type="number"] {
    background-image: none;
    padding-right: 12px;
}
.panel-sim-container .panel-sim-controls select:focus,
.panel-sim-container .panel-sim-controls input:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.18);
}
.panel-sim-container .panel-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
}
.panel-sim-container .panel-sim-button-row {
    display: flex;
    gap: 10px;
    margin-top: 18px;
    flex-wrap: wrap;
}
.panel-sim-container .panel-sim-controls .btn {
    border-radius: 4px;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 20px;
    font-weight: 700;
    border: 1px solid transparent;
    transition: background 0.2s ease, box-shadow 0.2s ease, color 0.2s ease, border-color 0.2s ease;
    cursor: pointer;
}
.panel-sim-container .panel-sim-controls .btn-primary {
    background: #00bfff;
    border-color: #00bfff;
    color: #0a0f1e;
}
.panel-sim-container .panel-sim-controls .btn-primary:hover {
    background: #33ccff;
    border-color: #33ccff;
    box-shadow: 0 0 14px rgba(0,191,255,0.45);
    color: #0a0f1e;
}
.panel-sim-container .panel-sim-controls .btn-outline-secondary {
    background: transparent;
    border-color: #2d3f55;
    color: #9ca3af;
}
.panel-sim-container .panel-sim-controls .btn-outline-secondary:hover {
    border-color: #ff6b35;
    color: #ff6b35;
    background: rgba(255,107,53,0.05);
}

.panel-sim-container .panel-sim-feedback {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #ff6b35;
    border-radius: 0 8px 8px 0;
    padding: 20px 24px;
    margin-bottom: 24px;
}
.panel-sim-container .panel-sim-feedback h3 {
    color: #ff6b35;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 12px 0;
    font-weight: 700;
}
.panel-sim-container .panel-sim-feedback #feedbackText {
    color: #c8d1e0;
    font-size: 0.9rem;
    line-height: 1.65;
}
.panel-sim-container .panel-sim-feedback #feedbackText strong {
    color: #00ff88;
}

.panel-sim-container .panel-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.panel-sim-container .panel-sim-history h3 {
    color: #00bfff;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.panel-sim-container .panel-sim-history table {
    color: #c8d1e0;
    font-size: 0.85rem;
    margin-bottom: 0;
    width: 100%;
}
.panel-sim-container .panel-sim-history table thead th {
    color: #767e8d;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f55;
    border-top: none;
    padding: 10px 8px;
    font-weight: 700;
    background: transparent;
}
.panel-sim-container .panel-sim-history table tbody td {
    border-top: 1px solid #1f2d3d;
    padding: 9px 8px;
    font-variant-numeric: tabular-nums;
    color: #c8d1e0;
}
.panel-sim-container .panel-sim-history table.table-striped tbody tr:nth-of-type(odd) td {
    background-color: rgba(0,191,255,0.04);
}
.panel-sim-container .panel-sim-history table.table-striped tbody tr:hover td {
    background-color: rgba(0,255,136,0.05);
}

.panel-sim-container .panel-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 16px;
    margin-bottom: 16px;
}
.panel-sim-container .panel-sim-chart-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px;
    height: 320px;
    position: relative;
}
.panel-sim-container .panel-sim-chart-card canvas {
    max-height: 100%;
}

@media (max-width: 768px) {
    .panel-sim-container {
        padding: 14px;
    }
    .panel-sim-container .panel-sim-header {
        flex-direction: column;
        align-items: flex-start;
    }
    .panel-sim-container .panel-sim-control-row {
        grid-template-columns: 1fr;
        gap: 6px;
    }
    .panel-sim-container .panel-sim-kpi-value {
        font-size: 1.4rem;
    }
    .panel-sim-container .panel-sim-briefing,
    .panel-sim-container .panel-sim-controls,
    .panel-sim-container .panel-sim-feedback,
    .panel-sim-container .panel-sim-history {
        padding: 16px 18px;
    }
}

/* --- EQIL a11y additions (adapter 1.1.0) --- */
.panel-sim-container :focus-visible,
button:focus-visible, select:focus-visible, input:focus-visible {
    outline: 3px solid #7dd3fc;
    outline-offset: 2px;
}
.panel-sim-debrief dl { display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 1rem; margin: 0.75rem 0; }
.panel-sim-debrief dt { font-weight: 600; }
.panel-sim-debrief dd { margin: 0; }
.panel-sim-debrief-flag { font-weight: 600; color: #f87171; }
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "1320";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        // 1.3: only the texts decide. Numeric values alone (0, 1, 2) no longer keep a decision in order: many
        // decisions with named options use them, and a fixed order there let the first or last option win.
        var nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
        return null;
    }
    function flat(o, pre, out, d) {
        if (!o || typeof o !== "object" || d > 4) { return out; }
        for (var k in o) {
            if (!Object.prototype.hasOwnProperty.call(o, k)) { continue; }
            var v = o[k];
            if (typeof v === "string") { out[pre + k] = v; }
            else if (v && typeof v === "object" && !Array.isArray(v)) { flat(v, pre + k + ".", out, d + 1); }
        }
        return out;
    }
    function squash(s) { return String(s).replace(/\s+/g, " ").replace(/^ | $/g, ""); }
    var decoder = null;
    function decode(s) {
        if (s.indexOf("&") < 0) { return s; }
        try { decoder = decoder || document.createElement("textarea"); decoder.innerHTML = s; return decoder.value; } catch (e) { return s; }
    }
    // a value with inline markup is several text nodes on the page: one piece per stretch between tags
    function pieces(v) {
        var p = String(v).split(/<[^>]*>/);
        for (var i = 0; i < p.length; i++) { p[i] = decode(p[i]); }
        return p;
    }
    var LETTER = /[A-Za-zÀ-ɏ]/;
    function quote(s) { return s.replace(/[.*+?^$()|[\]\\]/g, "\\$&"); }
    function template(a, b) {
        var parts = a.split(/\{(\w+)\}/), names = [], rx = "", lit = 0;
        for (var i = 0; i < parts.length; i++) {
            if (i % 2) { names.push(parts[i]); rx += (i === parts.length - 2 && parts[i + 1] === "") ? "([^\\s.,;:!?)]+)" : "(.+?)"; }
            else { rx += quote(parts[i]); lit += parts[i].replace(/\s/g, "").length; }
        }
        if (!names.length || lit < 10) { return null; }
        try { return { rx: new RegExp(rx), names: names, to: b }; } catch (e) { return null; }
    }
    function buildMaps(L) {
        var T = tables();
        if (!T || !T[L] || typeof T[L] !== "object") { return null; }
