            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    credibilityScore: 0,
                    memoScore: 0,
                    biasRemaining: 100,
                    estimateHistory: [],
                    credibilityHistory: [],
                    biasHistory: [],
                    seHistory: [],
                    lastEstimate: null,
                    lastSE: null,
                    lastP: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    estimator: 'pooled_ols',
                    seType: 'conventional',
                    diagnostic: 'none',
                    memoFraming: 'precise_point'
                };
            }
            var self = this;
            setTimeout(function() {
                self._syncControlsFromDecisions(state);
                self._updateBriefing(state);
            }, 50);
        }

        _syncControlsFromDecisions(state) {
            // On resume the framework restores decisions but the DOM still showed the authored
            // defaults, so the player saw values that were not their own.
            var dec = (state && state.decisions) || {};
            var map = {
                estimatorSelect: dec.estimator,
                seSelect: dec.seType,
                diagnosticSelect: dec.diagnostic,
                memoFraming: dec.memoFraming
            };
            Object.keys(map).forEach(function(id) {
                if (map[id] === undefined || map[id] === null) return;
                var el = document.getElementById(id);
                if (el) el.value = map[id];
            });
        }

        validateDecisions(decisions) {
            var estSel = document.getElementById('estimatorSelect');
            if (estSel) decisions.estimator = estSel.value;
            var seSel = document.getElementById('seSelect');
            if (seSel) decisions.seType = seSel.value;
            var diagSel = document.getElementById('diagnosticSelect');
            if (diagSel) decisions.diagnostic = diagSel.value;
            var memoSel = document.getElementById('memoFraming');
            if (memoSel) decisions.memoFraming = memoSel.value;

            if (!ESTIMATES[decisions.estimator]) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_estimator'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var period = state.currentPeriod;
            var est = ESTIMATES[d.estimator] || ESTIMATES.pooled_ols;
            var se = (d.seType === 'clustered') ? est.seClust : est.seConv;
            var tStat = est.beta / se;
            var pValue = approxPValue(tStat);

            var score = this._scoreRound(period, d, est, se, tStat, pValue);

            state.domainState.credibilityScore += score.credibility;
            state.domainState.memoScore += score.memo;

            var newBias = 100 - est.biasAddressed - score.biasFromExtras;
            if (newBias < 0) newBias = 0;
            state.domainState.biasRemaining = newBias;

            state.domainState.estimateHistory.push(est.beta);
            state.domainState.credibilityHistory.push(state.domainState.credibilityScore);
            state.domainState.biasHistory.push(newBias);
            state.domainState.seHistory.push(se);
            state.domainState.lastEstimate = est.beta;
            state.domainState.lastSE = se;
            state.domainState.lastP = pValue;

            // Platform score: the same 0-100 composite getPerformanceSummary reports (credibility over 200 weighted 70, memo over 72 weighted 30), on the running totals, rounded to an integer.
            var pfCred = Math.max(0, Math.min(1, (state.domainState.credibilityScore || 0) / 200)) * 70;
            var pfMemo = Math.max(0, Math.min(1, (state.domainState.memoScore || 0) / 72)) * 30;
            var pfScore = Math.max(0, Math.min(100, Math.round(pfCred + pfMemo)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: pfScore });

            var feedbackEl = document.getElementById('feedbackText');
            if (feedbackEl) feedbackEl.innerHTML = score.feedback || window.mySimulation.t('feedback_placeholder');

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                estimator: d.estimator,
                seType: d.seType,
                diagnostic: d.diagnostic,
                memoFraming: d.memoFraming,
                beta: est.beta,
                se: se,
                tStat: tStat,
                pValue: pValue,
                credibilityGain: score.credibility,
                memoGain: score.memo,
                biasRemaining: newBias
            };
        }

        _scoreRound(period, d, est, se, tStat, pValue) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var cred = 0;
            var memo = 0;
            var biasFromExtras = 0;
            var fb = '';

            // Estimator score per round
            if (period === 1) {
                if (d.estimator === 'pooled_ols')      { cred += 8;  fb = appendFb(fb, t('fb_round1_pooled')); }
                else if (d.estimator === 'fe_oneway')  { cred += 16; fb = appendFb(fb, t('fb_round1_fe_one')); }
                else if (d.estimator === 'fe_twoway')  { cred += 18; fb = appendFb(fb, t('fb_round1_fe_two')); }
                else if (d.estimator === 'random_effects') { cred += 4; fb = appendFb(fb, t('fb_re_general')); }
            } else if (period === 2) {
                if (d.estimator === 'pooled_ols')      { cred += 0;  fb = appendFb(fb, t('fb_round2_pooled')); }
                else if (d.estimator === 'fe_oneway')  { cred += 18; fb = appendFb(fb, t('fb_round2_fe_one')); }
                else if (d.estimator === 'fe_twoway')  { cred += 22; fb = appendFb(fb, t('fb_round2_fe_two')); }
                else if (d.estimator === 'random_effects') { cred += 6; fb = appendFb(fb, t('fb_re_general')); }
            } else if (period === 3) {
                if (d.estimator === 'pooled_ols')      { cred += 0;  fb = appendFb(fb, t('fb_round3_pooled')); }
                else if (d.estimator === 'fe_oneway')  { cred += 14; fb = appendFb(fb, t('fb_round3_fe_one')); }
                else if (d.estimator === 'fe_twoway')  { cred += 26; fb = appendFb(fb, t('fb_round3_fe_two')); }
                else if (d.estimator === 'random_effects') {
                    if (d.diagnostic === 'hausman') { cred += 8; fb = appendFb(fb, t('fb_round3_re_haus')); }
                    else { cred += 0; fb = appendFb(fb, t('fb_round3_re_no_haus')); }
                }
            } else {
                if (d.estimator === 'fe_twoway')       { cred += 22; fb = appendFb(fb, t('fb_round4_fe_two')); }
                else if (d.estimator === 'fe_oneway')  { cred += 14; fb = appendFb(fb, t('fb_round4_fe_one')); }
                else if (d.estimator === 'pooled_ols') { cred += 0;  fb = appendFb(fb, t('fb_round4_pooled')); }
                else if (d.estimator === 'random_effects') { cred += 4; fb = appendFb(fb, t('fb_re_general')); }
            }

            // SE-treatment score
            var feIsh = (d.estimator === 'fe_oneway' || d.estimator === 'fe_twoway');
            if (d.seType === 'clustered' && feIsh) {
                cred += 14;
                if (period >= 3) fb = appendFb(fb, t('fb_clustered_good'));
            } else if (d.seType === 'conventional' && feIsh && period >= 3) {
                fb = appendFb(fb, t('fb_unclustered_warning'));
            } else if (d.seType === 'clustered' && d.estimator === 'pooled_ols') {
                cred += 4;
            } else if (d.seType === 'clustered' && d.estimator === 'random_effects') {
                cred += 6;
            }

            // Diagnostic score
            if (d.diagnostic === 'hausman') {
                cred += (d.estimator === 'random_effects' || d.estimator === 'fe_twoway' || d.estimator === 'fe_oneway') ? 10 : 4;
                if (period >= 2) fb = appendFb(fb, t('fb_hausman'));
            } else if (d.diagnostic === 'parallel_trends') {
                cred += 14;
                biasFromExtras += 8;
                fb = appendFb(fb, t('fb_pt_test'));
            } else if (d.diagnostic === 'heterogeneity') {
                cred += 12;
                fb = appendFb(fb, t('fb_het'));
            } else if (d.diagnostic === 'none' && period >= 3) {
                fb = appendFb(fb, t('fb_no_diag'));
            }

            // Memo framing score
            if (d.memoFraming === 'precise_point') {
                memo += 0;
                if (period >= 3) fb = appendFb(fb, t('fb_memo_point'));
            } else if (d.memoFraming === 'estimate_with_ci') {
                memo += 8;
                if (period >= 3) fb = appendFb(fb, t('fb_memo_ci'));
            } else if (d.memoFraming === 'stated_assumption') {
                memo += 14;
                if (period >= 3) fb = appendFb(fb, t('fb_memo_assumption'));
            } else if (d.memoFraming === 'range_with_caveat') {
                memo += 18;
                if (period >= 3) fb = appendFb(fb, t('fb_memo_range'));
            }

            // Numeric summary line
            var betaPct = ((est.beta >= 0 ? '+' : '') + (est.beta * 100).toFixed(1) + '%');
            var pStr = (pValue < 0.001) ? '< 0.001' : pValue.toFixed(3);
            var summary = t('fb_run_summary')
                .replace('{beta}', betaPct)
                .replace('{se}', se.toFixed(3))
                .replace('{t}', tStat.toFixed(1))
                .replace('{p}', pStr);
            fb = summary + '<br><br>' + fb;

            return { credibility: cred, memo: memo, biasFromExtras: biasFromExtras, feedback: fb };
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            // Past round 4 the workshop is over. The index used to clamp, leaving the round 4
            // briefing and a live Run Specification button on screen with nothing left to run.
            var over = period > 4;
            var controls = document.querySelector('.panel-sim-controls');
            var row = document.querySelector('.panel-sim-button-row');
            if (row && row.style) row.style.display = over ? 'none' : '';
            if (controls && controls.style) controls.style.display = over ? 'none' : '';
            if (over) {
                var endT = document.getElementById('roundTitle');
                var endB = document.getElementById('briefingText');
                if (endT) endT.textContent = this._t('round_complete_title', 'Workshop complete');
                if (endB) endB.innerHTML = this._t('round_complete_brief', 'All four specifications are on the record.');
                return;
            }
            var idx = Math.min(Math.max(period - 1, 0), 3);
            var keys = [
                { titleKey: 'round1_title', briefKey: 'round1_brief' },
                { titleKey: 'round2_title', briefKey: 'round2_brief' },
                { titleKey: 'round3_title', briefKey: 'round3_brief' },
                { titleKey: 'round4_title', briefKey: 'round4_brief' }
            ];
            var tFn = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = tFn(keys[idx].titleKey);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = tFn(keys[idx].briefKey);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('credibilityDisplay', 'domainState.credibilityScore', function(v) {
                return Math.round(v || 0);
            });
            uiManager.bind('biasDisplay', 'domainState.biasRemaining', function(v) {
                if (v == null) return '100%';
                return Math.round(v) + '%';
            });
            uiManager.bind('estimateDisplay', 'domainState.lastEstimate', function(v) {
                if (v == null) return '—';
                return (v >= 0 ? '+' : '') + (v * 100).toFixed(1) + '%';
            });
            uiManager.bind('memoScoreDisplay', 'domainState.memoScore', function(v) {
                return Math.round(v || 0);
            });
        }

