        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var est = ds.estimateHistory || [];
            var cred = ds.credibilityHistory || [];
            var labels = est.map(function(_, i) { return 'R' + (i + 1); });
            var labelsCred = cred.map(function(_, i) { return 'R' + (i + 1); });
            return {
                estimateChart: {
                    labels: labels,
                    datasets: [{ data: est.map(function(v) { return +(v * 100).toFixed(1); }) }]
                },
                credibilityChart: {
                    labels: labelsCred,
