                }
            };
        }

        getPerformanceSummary(history) {
            // Prefer the live state, but fall back to the history argument the framework
            // passes in so the summary still works from a restored run.
            var ds = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.domainState : null;
            if (!ds && history && history.length) {
                var lastR = history[history.length - 1].results || {};
                ds = {
                    credibilityScore: lastR.credibilityScore || 0,
                    memoScore: lastR.memoScore || 0,
                    biasRemaining: lastR.biasRemaining
                };
            }
            if (!ds) return {};
            var totalCred = ds.credibilityScore || 0;
            var totalMemo = ds.memoScore || 0;
            var t = window.mySimulation.t.bind(window.mySimulation);

            var performance = 'naive';
            if (totalCred >= 60)  performance = 'junior';
            if (totalCred >= 100) performance = 'council';
            if (totalCred >= 140) performance = 'chief';
            // Declared scoring change. memoScore was computed every round and then ignored by the
            // band, so a run could frame the result as a precise point estimate - the exact
            // anti-pattern this workshop teaches against - and still be graded Chief Economist on
            // credibility alone. The memo now carries weight, and a top band requires that the
            // memo was at least half-credible.
            var MAX_CRED = 200;
            var MAX_MEMO = 72;
            var credPart = Math.max(0, Math.min(1, totalCred / MAX_CRED)) * 70;
            var memoPart = Math.max(0, Math.min(1, totalMemo / MAX_MEMO)) * 30;
            var composite = Math.round((credPart + memoPart) * 10) / 10;
            if (performance === 'chief' && totalMemo < MAX_MEMO * 0.5) performance = 'council';
            var performanceLabel = this._t('perf_' + performance, performance);

            var insights = [
                t('insight_1'),
                t('insight_2'),
                t('insight_3')
            ];

            return {
                credibilityScore: totalCred,
                memoScore: totalMemo,
                biasRemaining: ds.biasRemaining,
                performance: performance,
                performanceKey: performance,
                performanceLabel: performanceLabel,
                // The reporting layer reads a different one of these depending on its version, so
                // emit all four and keep them identical.
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            // Without this method the framework computes the debrief and throws it away.
            var s = summary || {};
            var esc = function(v) { return String(v === undefined || v === null ? '' : v); };
            var rows = [
                [this._t('sum_score', 'Workshop score'), esc(s.overallScore) + ' / 100'],
                [this._t('sum_band', 'Band'), esc(s.performanceLabel || s.performance)],
                [this._t('sum_cred', 'Credibility points'), esc(s.credibilityScore) + ' / 200'],
                [this._t('sum_memo', 'Memo-framing points'), esc(s.memoScore) + ' / 72'],
                [this._t('sum_bias', 'Bias remaining'), esc(s.biasRemaining) + '%']
            ];
            var html = '<div class="panel-sim-debrief"><h3>' + this._t('debrief_title', 'Workshop Review') + '</h3><dl>';
            rows.forEach(function(r) { html += '<dt>' + r[0] + '</dt><dd>' + r[1] + '</dd>'; });
            html += '</dl>';
            if (s.memoScore !== undefined && s.memoScore < 36) {
                html += '<p class="panel-sim-debrief-flag">' + this._t('flag_memo', 'The memo framing did not carry the uncertainty the estimate deserved.') + '</p>';
            }
            if (s.insights && s.insights.length) {
                html += '<ul class="panel-sim-debrief-insights">';
                s.insights.forEach(function(i) { html += '<li>' + i + '</li>'; });
                html += '</ul>';
            }
            return html + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.currentPeriod >= 2 && results.estimator === 'pooled_ols') {
                return window.mySimulation.t('hint_naive');
            }
            if (results.estimator === 'random_effects' && results.diagnostic !== 'hausman') {
                return window.mySimulation.t('hint_re_no_hausman');
            }
            if (state.currentPeriod >= 4 && results.seType === 'conventional'
                && (results.estimator === 'fe_oneway' || results.estimator === 'fe_twoway')) {
                return window.mySimulation.t('hint_unclustered');
            }
            if (state.currentPeriod >= 4 && results.diagnostic === 'none') {
                return window.mySimulation.t('hint_no_robustness');
            }
            return null;
        }

